  function renderCakeRequests(){const body=$('#cakeRequestsBody');if(!body)return;body.replaceChildren();const count=$('#cakeRequestCount');if(count)count.textContent=`${cakeRequests.length} ${cakeRequests.length===1?'request':'requests'}`;if(!cakeRequests.length)return emptyRow(body,6,'No custom cake requests yet.');const labels={classic:'Classic',floral:'Floral',drip:'Drip cake',celebration:'Celebration',half_kg:'½ kg',one_kg:'1 kg',two_kg:'2 kg',vanilla:'Vanilla',chocolate:'Chocolate',strawberry:'Strawberry',red_velvet:'Red velvet'};const allowed=['submitted','contacted','quoted','accepted','completed','cancelled'];for(const request of cakeRequests){const tr=document.createElement('tr'),ref=document.createElement('td');ref.innerHTML=`<span class="table-primary">CAKE-${esc(String(request.id).slice(0,8).toUpperCase())}</span><span class="table-secondary">${esc(stamp(request.created_at))}</span>`;const customer=document.createElement('td');customer.innerHTML=`<span class="table-primary">${esc(request.customer_name)}</span><span class="table-secondary">${esc(request.customer_phone)}</span>`;const design=document.createElement('td');design.textContent=labels[request.design_key]||request.design_key;const details=document.createElement('td');details.innerHTML=`<span class="table-primary">${esc(labels[request.size_key]||request.size_key)} · ${esc(labels[request.flavor_key]||request.flavor_key)}</span><span class="table-secondary">${esc(request.icing_color)}${request.message_text?` · “${esc(request.message_text)}”`:''}</span>`;const price=document.createElement('td');price.textContent=money(request.estimated_total_bdt);const status=document.createElement('td'),select=document.createElement('select');select.className='admin-select';select.setAttribute('aria-label',`Cake request status for ${request.customer_name}`);for(const value of allowed){const option=document.createElement('option');option.value=value;option.textContent=value.replaceAll('_',' ');select.append(option)}select.value=request.status;select.onchange=async()=>{select.disabled=true;const {data,error}=await sb.from('cake_requests').update({status:select.value}).eq('id',request.id).select('id').maybeSingle();select.disabled=false;if(error||!data){toast(`Could not update cake request: ${error?.message||'administrator access required'}`);select.value=request.status;return}request.status=select.value;toast('Cake request status updated.')};status.append(select);tr.append(ref,customer,design,details,price,status);body.append(tr)}}
  function renderAll(stats){const metricOrders=Number(stats?.total_orders??orders.length),pending=Number(stats?.pending_orders??orders.filter(o=>o.status==='pending_confirmation').length),sales=Number(stats?.total_sales_bdt??orders.filter(o=>o.status!=='cancelled').reduce((s,o)=>s+Number(o.total_bdt),0)),low=Number(stats?.low_stock_products??products.filter(p=>p.is_active&&Number(p.stock_quantity)<=Number(p.low_stock_threshold)).length);$('#metricOrders').textContent=metricOrders.toLocaleString(bn?'bn-BD':'en-BD');$('#metricPending').textContent=pending.toLocaleString(bn?'bn-BD':'en-BD');$('#metricSales').textContent=money(sales);$('#metricLow').textContent=low.toLocaleString(bn?'bn-BD':'en-BD');$('#metricOrdersNote').textContent=`${products.length} ${copy.items}`;renderChart();renderStatus();renderRecent();renderOrders();renderCakeRequests();renderProducts();renderCategoryManagement();renderInventory();renderZones();renderCustomers();$('#lowStockBadge').textContent=`${low} ${copy.lowStock}`;$('#customerCount').textContent=`${new Set(orders.map(o=>o.user_id)).size} ${copy.customers}`}
  function renderChart(){const el=$('#ordersChart');el.replaceChildren();const now=new Date(),days=[];for(let i=6;i>=0;i--){const d=new Date(now);d.setHours(0,0,0,0);d.setDate(now.getDate()-i);const next=new Date(d);next.setDate(d.getDate()+1);const total=orders.filter(o=>{const at=new Date(o.created_at);return at>=d&&at<next}).length;days.push({date:d,total})}const max=Math.max(1,...days.map(d=>d.total));for(const d of days){const col=document.createElement('div');col.className='chart-col';const bar=document.createElement('div');bar.className='chart-bar';bar.style.height=`${Math.max(3,d.total/max*83)}%`;bar.title=`${date(d.date)}: ${d.total}`;const label=document.createElement('small');label.textContent=d.date.toLocaleDateString(bn?'bn-BD':'en-BD',{weekday:'short'});col.append(bar,label);el.append(col)}}
  function renderStatus(){const el=$('#statusList');el.replaceChildren();for(const status of statuses){const count=orders.filter(o=>o.status===status).length,row=document.createElement('div');row.className='status-row';const dot=document.createElement('i');dot.className='status-dot';dot.style.background=status==='cancelled'?'#d76d6d':status==='pending_confirmation'?'#eab94c':status==='delivered'?'#18a078':'#3b8ac0';const name=document.createElement('span');name.textContent=statusText(status);const val=document.createElement('b');val.textContent=count;const meter=document.createElement('div');meter.className='status-meter';const fill=document.createElement('i');fill.style.width=`${orders.length?count/orders.length*100:0}%`;fill.style.background=dot.style.background;meter.append(fill);row.append(dot,name,val,meter);el.append(row)}}
  function formatOrderReference(order){const date=new Date(order.created_at||Date.now()),year=String(date.getFullYear()).slice(-2),hex=String(order.id||'').replace(/-/g,'');if(!/^[0-9a-f]{32}$/i.test(hex))return `FST-${year}-${String(order.order_number||'ORDER').toUpperCase()}`;let binary='';for(let i=0;i<hex.length;i+=2)binary+=String.fromCharCode(parseInt(hex.slice(i,i+2),16));const token=btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');return `FST-${year}-${token}`}
  function printInvoices(invoiceOrders,heading){if(!invoiceOrders.length){toast(bn?'কোনো অর্ডার নেই।':'No orders to invoice.');return}const printWindow=window.open('','_blank');if(!printWindow){toast(bn?'ইনভয়েস খুলতে পপ-আপ অনুমতি দিন।':'Allow pop-ups to open the invoice.');return}const methodLabels={cod:'Cash on Delivery',bkash:'bKash',nagad:'Nagad',rocket:'Rocket'},docs=invoiceOrders.map(order=>{const itemRows=(order.order_items||[]).map(item=>{const quantity=Number(item.quantity)||0,unit=Number(item.unit_price_bdt)||0,line=Number(item.line_total_bdt)||unit*quantity,name=bn?(item.product_name_bn||item.product_name_en):(item.product_name_en||item.product_name_bn);return `<tr><td>${esc(name||'—')}</td><td class="num">${quantity}</td><td class="num">${money(unit)}</td><td class="num">${money(line)}</td></tr>`}).join(''),method=methodLabels[order.payment_method]||order.payment_method||'—';return `<article class="invoice"><header><div><div class="brand">❄ Frostly</div><div class="muted">Frozen Food for a Better Tomorrow</div><div class="muted">Chattogram, Bangladesh</div></div><div class="invoice-title"><h1>${bn?'ইনভয়েস':'INVOICE'}</h1><b>${esc(formatOrderReference(order))}</b><span>${esc(stamp(order.created_at))}</span></div></header><section class="billto"><div><small>${bn?'ক্রেতা':'BILL TO'}</small><b>${esc(order.customer_name||'—')}</b><span>${esc(order.customer_phone||'')}</span></div><div><small>${bn?'ডেলিভারির ঠিকানা':'DELIVERY ADDRESS'}</small><b>${esc(order.delivery_area||'')}</b><span>${esc(order.delivery_address||'')}</span></div><div><small>${bn?'পেমেন্ট':'PAYMENT'}</small><b>${esc(method)}</b><span>${esc(statusText(order.status))}</span></div></section><table><thead><tr><th>${bn?'পণ্য':'ITEM'}</th><th class="num">${bn?'পরিমাণ':'QTY'}</th><th class="num">${bn?'একক দাম':'UNIT PRICE'}</th><th class="num">${bn?'মোট':'TOTAL'}</th></tr></thead><tbody>${itemRows||`<tr><td colspan="4">—</td></tr>`}</tbody></table><section class="totals"><div><span>${bn?'সাবটোটাল':'Subtotal'}</span><b>${money(order.subtotal_bdt)}</b></div><div><span>${bn?'ডেলিভারি চার্জ':'Delivery fee'}</span><b>${money(order.delivery_fee_bdt)}</b></div><div class="grand"><span>${bn?'সর্বমোট':'Total'}</span><b>${money(order.total_bdt)}</b></div></section>${order.delivery_instructions?`<p class="notes"><b>${bn?'ডেলিভারি নির্দেশনা':'Delivery instructions'}:</b> ${esc(order.delivery_instructions)}</p>`:''}<footer>Thank you for ordering from Frostly.</footer></article>`}).join('');printWindow.document.open();printWindow.document.write(`<!doctype html><html lang="${bn?'bn':'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(heading)}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{margin:0;color:#142a3c;font:12px Inter,Arial,sans-serif}.invoice{min-height:260mm;position:relative;padding-bottom:18mm;break-after:page;page-break-after:always}.invoice:last-child{break-after:auto;page-break-after:auto}header{display:flex;justify-content:space-between;gap:20px;padding-bottom:20px;border-bottom:2px solid #16846e}.brand{font-size:24px;font-weight:800;color:#08745f}.muted,.invoice-title span{display:block;color:#6b7d8a;font-size:10px;margin-top:4px}.invoice-title{text-align:right}.invoice-title h1{font-size:20px;letter-spacing:.08em;margin:0 0 8px}.invoice-title b{font-size:12px}.billto{display:grid;grid-template-columns:1fr 1.5fr 1fr;gap:16px;padding:20px 0}.billto small{display:block;color:#6b7d8a;font-size:9px;letter-spacing:.05em;margin-bottom:6px}.billto b,.billto span{display:block;margin:3px 0;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;margin-top:8px}th,td{padding:10px 8px;border-bottom:1px solid #dce5e9;text-align:left}th{background:#f3f8f7;font-size:9px;letter-spacing:.04em}.num{text-align:right;white-space:nowrap}.totals{width:260px;margin:18px 0 0 auto}.totals div{display:flex;justify-content:space-between;gap:15px;padding:6px 0}.totals .grand{border-top:1px solid #a9bbc4;margin-top:5px;padding-top:11px;font-size:14px}.notes{margin-top:24px;padding:12px;background:#f5f8fa;border-radius:5px}.invoice footer{position:absolute;bottom:0;width:100%;padding-top:10px;border-top:1px solid #dce5e9;text-align:center;color:#71828e;font-size:10px}@media screen{body{background:#eef3f5;padding:20px}.invoice{max-width:800px;margin:0 auto 20px;padding:35px;background:white;box-shadow:0 3px 16px #102a4315}.invoice footer{position:static;margin-top:50px}.print-hint{max-width:800px;margin:0 auto 12px;color:#516777;font-size:13px}}@media print{.print-hint{display:none}}</style></head><body><div class="print-hint">${bn?'প্রিন্ট ডায়ালগে Save as PDF নির্বাচন করে ইনভয়েস ডাউনলোড করুন।':'In the print dialog, choose Save as PDF to download the invoices.'}</div>${docs}</body></html>`);printWindow.document.close();setTimeout(()=>{printWindow.focus();printWindow.print()},450)}
  function createOrderRow(order,compact=false){
    const tr=document.createElement('tr'),reference=formatOrderReference(order),id=document.createElement('td');
    id.innerHTML=`<span class="table-primary">${esc(reference)}</span><span class="table-secondary">${esc(date(order.created_at))}</span>`;tr.append(id);
    const customer=document.createElement('td'),methodLabels={cod:'Cash on Delivery',bkash:'bKash',nagad:'Nagad',rocket:'Rocket'},paymentLabel=methodLabels[order.payment_method]||esc(order.payment_method||'—');
    customer.innerHTML=`<span class="table-primary">${esc(order.customer_name)}</span><span class="table-secondary">${esc(order.customer_phone)}</span>${!compact?`<span class="table-secondary">Payment: ${paymentLabel} · ${esc(order.payment_status||'due')}</span>${order.payment_reference?`<span class="table-secondary">Txn ID: ${esc(order.payment_reference)}</span>`:''}`:''}`;tr.append(customer);
    const area=document.createElement('td');area.innerHTML=`<span class="table-primary">${esc(order.delivery_area)}</span><span class="table-secondary">${compact?esc(stamp(order.created_at)):esc(order.delivery_address||'')}</span>`;tr.append(area);
    if(compact){const total=document.createElement('td');total.textContent=money(order.total_bdt);tr.append(total);const state=document.createElement('td');state.innerHTML=`<span class="pill ${pillClass(order.status)}">${esc(statusText(order.status))}</span>`;tr.append(state);return tr}
    const items=document.createElement('td');items.innerHTML=`<span class="table-primary">${money(order.total_bdt)}</span><span class="table-secondary">${(order.order_items||[]).map(item=>`${esc(bn?item.product_name_bn:item.product_name_en)} × ${Number(item.quantity)}`).join(' · ')||'—'}</span>`;tr.append(items);
    const placed=document.createElement('td');placed.textContent=stamp(order.created_at);tr.append(placed);
    const state=document.createElement('td'),select=document.createElement('select');select.className='inline-select';select.setAttribute('aria-label',`Order ${reference} status`);
    for(const status of statuses){const option=document.createElement('option');option.value=status;option.textContent=statusText(status);option.selected=status===order.status;select.append(option)}
    const save=document.createElement('button');save.className='admin-btn small';save.type='button';save.textContent=copy.save;save.onclick=async()=>{save.disabled=true;const {error}=await sb.rpc('admin_set_order_status',{p_order_id:order.id,p_status:select.value,p_note:''});if(error){save.disabled=false;toast(`${copy.statusError} ${error.message}`);return}toast(copy.saved);await loadData()};
    state.append(select,document.createElement('br'),save);
    if(order.payment_status==='pending_verification'&&['superadmin','admin','ordermanager'].includes(currentRole)){const verify=document.createElement('button');verify.type='button';verify.className='admin-btn small primary';verify.style.marginTop='6px';verify.textContent='Mark payment verified';verify.onclick=async()=>{verify.disabled=true;const {data,error}=await sb.from('orders').update({payment_status:'collected'}).eq('id',order.id).eq('payment_status','pending_verification').select('id').maybeSingle();if(error||!data){verify.disabled=false;toast(`Could not verify payment. ${error?.message||'Refresh orders and try again.'}`);return}toast('Payment marked verified.');await loadData()};state.append(document.createElement('br'),verify)}
    const invoiceButton=document.createElement('button');invoiceButton.type='button';invoiceButton.className='admin-btn small';invoiceButton.style.marginTop='6px';invoiceButton.textContent=bn?'ইনভয়েস ডাউনলোড':'Download invoice';invoiceButton.onclick=()=>printInvoices([order],`${formatOrderReference(order)}-invoice`);state.append(document.createElement('br'),invoiceButton);
    tr.append(state);return tr;
  }  function renderRecent(){const body=$('#recentOrdersBody');body.replaceChildren();if(!orders.length)return emptyRow(body,5,copy.orders);orders.slice(0,7).forEach(o=>body.append(createOrderRow(o,true)))}
  function renderOrders(){const body=$('#ordersBody'),q=($('#orderSearch')?.value||'').toLowerCase(),status=$('#orderStatusFilter')?.value||'';body.replaceChildren();const processing=orders.filter(o=>!['delivered','cancelled'].includes(o.status)).length,delivered=orders.filter(o=>o.status==='delivered').length;$('#processingOrderCount').textContent=processing;$('#downloadProcessingInvoicesButton').disabled=processing===0;$('#deliveredOrderCount').textContent=delivered;for(const [id,bucket] of [['processingOrdersButton','processing'],['deliveredOrdersButton','delivered']]){$(`#${id}`).classList.toggle('active',orderBucket===bucket);$(`#${id}`).setAttribute('aria-selected',String(orderBucket===bucket))}const rows=orders.filter(o=>(orderBucket==='all'||orderBucket==='processing'&&!['delivered','cancelled'].includes(o.status)||orderBucket==='delivered'&&o.status==='delivered')&&(!status||status===o.status)&&`${formatOrderReference(o)} ${o.order_number} ${o.customer_name} ${o.customer_phone} ${o.delivery_area}`.toLowerCase().includes(q));if(!rows.length)return emptyRow(body,6,copy.noMatch);rows.forEach(o=>body.append(createOrderRow(o)))}
  function renderProducts(){const body=$('#productsBody'),q=($('#productSearch')?.value||'').toLowerCase(),filter=$('#productFilter')?.value||'all';body.replaceChildren();const rows=products.filter(p=>{const match=`${p.name_en} ${p.name_bn} ${p.sku}`.toLowerCase().includes(q),low=Number(p.stock_quantity)<=Number(p.low_stock_threshold);return match&&(filter==='all'||filter==='active'&&p.is_active||filter==='inactive'&&!p.is_active||filter==='low'&&low)});if(!rows.length)return emptyRow(body,6,copy.noProducts);for(const p of rows){const tr=document.createElement('tr'),name=document.createElement('td');name.innerHTML=`<span class="table-primary">${esc(bn?p.name_bn:p.name_en)}</span><span class="table-secondary">${esc(bn?p.name_en:p.name_bn)}</span>`;tr.append(name);const sku=document.createElement('td');sku.textContent=p.sku;tr.append(sku);const price=document.createElement('td');price.textContent=money(p.price_bdt);tr.append(price);const stock=document.createElement('td');stock.innerHTML=`${Number(p.stock_quantity)}${Number(p.stock_quantity)<=Number(p.low_stock_threshold)?' <span class="pill yellow">Low</span>':''}`;tr.append(stock);const active=document.createElement('td');active.innerHTML=`<span class="pill ${p.is_active?'green':'red'}">${p.is_active?copy.active:copy.inactive}</span>`;tr.append(active);const action=document.createElement('td'),edit=document.createElement('button');edit.className='admin-btn small';edit.textContent=copy.edit;edit.onclick=()=>editProduct(p);action.append(edit);tr.append(action);body.append(tr)}}
  function populateCategories(){const select=$('#productCategory'),selected=select.value;select.replaceChildren(new Option(bn?'ক্যাটাগরি ছাড়া':'Uncategorized',''));for(const c of categories.filter(item=>item.is_active)){const op=new Option(bn?c.name_bn:c.name_en,c.id);select.append(op)}select.value=selected}
  function renderCategoryManagement(){const body=$('#categoriesBody');if(!body)return;body.replaceChildren();if(!categories.length)return emptyRow(body,4,'No categories found. Add your first category above.');for(const category of categories){const tr=document.createElement('tr'),name=document.createElement('td'),slug=document.createElement('td'),visibility=document.createElement('td'),actions=document.createElement('td');name.innerHTML=`<span class="table-primary">${esc(category.name_en)}</span><span class="table-secondary">${esc(category.name_bn)}</span>`;slug.textContent=category.slug;visibility.innerHTML=`<span class="pill ${category.is_active?'green':'red'}">${category.is_active?copy.active:copy.inactive}</span>`;const edit=document.createElement('button');edit.type='button';edit.className='admin-btn small';edit.textContent=copy.edit;edit.onclick=()=>{const form=$('#categoryForm');form.elements.id.value=category.id;form.elements.name_en.value=category.name_en;form.elements.name_bn.value=category.name_bn;form.elements.slug.value=category.slug;form.elements.is_active.checked=category.is_active;$('#saveCategoryButton').textContent='Update category';$('#cancelCategoryEdit').hidden=false;form.scrollIntoView({behavior:'smooth',block:'center'})};actions.append(edit);tr.append(name,slug,visibility,actions);body.append(tr)}}
  async function saveCategory(event){event.preventDefault();const form=event.currentTarget,data=new FormData(form),nameEn=String(data.get('name_en')).trim(),slug=String(data.get('slug')).trim()||nameEn.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!slug){toast('Enter a URL-friendly English category name or slug.');return}const payload={name_en:nameEn,name_bn:String(data.get('name_bn')).trim(),slug,is_active:form.elements.is_active.checked};const id=String(data.get('id')||'');const button=$('#saveCategoryButton');button.disabled=true;const result=id?await sb.from('categories').update(payload).eq('id',id):await sb.from('categories').insert(payload);button.disabled=false;if(result.error){toast(`${copy.saveError} ${result.error.message}`);return}resetCategoryForm();toast(copy.savedItem);await loadData()}
