  async function init(){localizeStatic();if(!sb)return showGate(copy.config);const {data:{session},error}=await sb.auth.getSession();if(error)return showGate(`${copy.error} ${error.message}`);if(!session)return showGate(copy.login,true);adminUserId=session.user.id;const {data:profile,error:profileError}=await sb.from('profiles').select('role,full_name,avatar_url').eq('id',session.user.id).maybeSingle();if(profileError)return showGate(`${copy.error} ${profileError.message}`);if(!roleViews[profile?.role])return showGate(copy.denied);currentRole=profile.role;currentEmail=session.user.email||'';gate.remove();root.style.display='';applyRoleNavigation();const email=session.user.email||'',fullName=profile.full_name||session.user.user_metadata?.full_name||email.split('@')[0]||'Admin',initial=fullName.trim().split(/\s+/).map(v=>v[0]).slice(0,2).join('').toUpperCase()||'A',avatar=profile.avatar_url||session.user.user_metadata?.avatar_url||'';$('#adminEmail').textContent=email;$('#adminDisplayName').textContent=fullName;$('#adminMenuName').textContent=fullName;$('#adminMenuEmail').textContent=email;showAdminAvatar($('#adminInitials'),avatar,initial);showAdminAvatar($('#adminMenuInitials'),avatar,initial);bind();const route=location.hash.slice(1);navTo(canView(route)?route:(roleViews[currentRole]||[])[0]);await loadData()}
  window.addEventListener('DOMContentLoaded',async()=>{await init();if(root.style.display!=='none'&&canView('settings')){bindSettings();await loadSiteSettings()}});
